/// <summary>
/// CB236 - Header charges for shrink wrap
/// </summary>
[ExtensionOf(formDataSourceStr(MarkupAutoSetup, MarkupAutoLine))]
final class METMarkupAutoSetupFrm_MarkupAutoLineDS_Extension
{
}

Method.Source:
/// <summary>
/// Form datasource Active method to enable/disable fields based on Shrink wrap setup on the Auto charges header
/// </summary>
/// <returns>int</returns>
int active()
{
    FormDataSource  markupAutoTableDS   =   this.formRun().dataSource(formDataSourceStr(MarkupAutoSetup, MarkupAutoTable)) as FormDataSource ;
    MarkupAutoTable markupAutoTable     =   markupAutoTableDS.cursor();
    int ret = next active();

    //If shrink wrap is set to yes, then, Category will not be considered for Auto charges calculation
    //Instead, New field 'Charges method' is considered for calculation based upon SO lines' Total weight and total Volume
    if(markupAutoTable.METAdvancedCalculation)
    {
        FormComboBoxControl chargesMethodControl, markupCategoryControl;
        chargesMethodControl = this.formRun().design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoLine_METChargesMethod)) as FormComboBoxControl;
        chargesMethodControl.visible(true);
        markupCategoryControl = this.formRun().design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoLine_MarkupCategory)) as FormComboBoxControl;
        markupCategoryControl.visible(false);
    }
    else
    {
        FormComboBoxControl chargesMethodControl, markupCategoryControl;
        chargesMethodControl = this.formRun().design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoLine_METChargesMethod)) as FormComboBoxControl;
        chargesMethodControl.visible(false);
        markupCategoryControl = this.formRun().design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoLine_MarkupCategory)) as FormComboBoxControl;
        markupCategoryControl.visible(true);
    }

    // CB748_PricingConditions
    // Update rebate controls enabled/mandatory from active method
    METMarkupAutoSetupHelper markupAutoSetupHelper = METMarkupAutoSetupHelper::newFromFormRun(this.formRun());
    markupAutoSetupHelper.updateRebateControlsEnabled(this);

    return ret;

}
